/* ===== VẬN DỤNG – LIÊN HỆ THỰC TẾ (trắc nghiệm, gợi ý ý tưởng cho bài tự luận) =====
   VL(mã bài) chọn bài; V(câu hỏi, [ĐÁP ÁN ĐÚNG, sai, sai, sai]) */
function VL(id) { _L = LESSONS.find((l) => l.id === id); }
function V(q, o, lv) { _push({ t: "mc", q, o, a: 0, lv, vd: 1 }); }

/* LỊCH SỬ */
VL("s1");
V("Về quê, em thấy ông bà còn giữ cối xay lúa, đèn dầu. Em nên làm gì để hiểu thêm lịch sử gia đình?",["Hỏi ông bà về công dụng, thời gian sử dụng và ghi chép lại","Vứt bỏ vì đã cũ","Bán đi lấy tiền","Không quan tâm vì không liên quan đến em"]);
V("Lớp em muốn giới thiệu lịch sử trường mình. Nguồn thông tin phù hợp nhất là",["Hỏi thầy cô lâu năm, xem ảnh, giấy khen, kỉ yếu của trường","Tự tưởng tượng ra câu chuyện","Chép bài viết về trường khác","Chỉ xem phim hoạt hình"]);
V("Vì sao nhiều nước xây bảo tàng và giữ gìn di tích lịch sử?",["Để mọi người hiểu quá khứ, tự hào và rút ra bài học cho hiện tại","Để thu hút khách mua sắm","Chỉ để làm nơi vui chơi","Vì không biết làm gì với đồ cũ"]);
VL("s2");
V("Em tìm thấy bức ảnh ông nội chụp năm 1975. Với lịch sử gia đình, bức ảnh này là",["Tư liệu hiện vật, có thể coi là tư liệu gốc","Tư liệu truyền miệng","Truyện cổ tích","Không phải tư liệu"]);
V("Để viết về lễ hội truyền thống ở quê, em nên kết hợp những nguồn nào?",["Lời kể của người lớn tuổi, sách báo và ảnh chụp lễ hội","Chỉ một bài trên mạng xã hội","Chỉ trí tưởng tượng","Chỉ hỏi bạn cùng lớp"]);
V("Hai tài liệu kể khác nhau về cùng một sự kiện. Em nên",["So sánh, tìm thêm nguồn tin cậy và ưu tiên tư liệu gốc","Tin ngay tài liệu đọc trước","Bỏ qua cả hai","Chọn tài liệu viết hay hơn"]);
VL("s3");
V("Tết Nguyên đán của người Việt được tính theo loại lịch nào?",["Âm lịch","Dương lịch","Lịch Hồi giáo","Không theo lịch nào"]);
V("Lịch treo tường nhà em ghi cả ngày âm và ngày dương. Điều này giúp",["Dùng ngày dương lịch cho học tập, làm việc và ngày âm lịch cho lễ, Tết truyền thống","Trang trí cho đẹp","Không có tác dụng","Chỉ để đếm tuổi"]);
V("Ông em sinh năm 1955. Năm 2026 ông em bao nhiêu tuổi (theo dương lịch)?",["71 tuổi","61 tuổi","81 tuổi","70 tuổi"]);
VL("s4");
V("Bảo tàng trưng bày răng hóa thạch Người tối cổ tìm thấy ở Việt Nam. Hiện vật giúp ta biết",["Việt Nam là một trong những nơi con người xuất hiện sớm","Người tối cổ biết viết chữ","Người tối cổ xây nhà cao tầng","Người tối cổ sống cách đây 100 năm"]);
V("Con người ngày nay khác Người tối cổ rõ nhất ở điểm nào?",["Bộ não phát triển, sáng tạo công cụ hiện đại và chữ viết","Đi bằng bốn chân","Cơ thể nhiều lông","Không biết dùng lửa"]);
V("Nhờ đâu vượn người dần trở thành người?",["Nhờ lao động, biết chế tạo và sử dụng công cụ","Nhờ ăn nhiều","Nhờ ngủ nhiều","Nhờ sống trên cây"]);
VL("s5");
