V("Tinh thần “cùng làm, cùng hưởng” của người nguyên thủy giống hoạt động nào ở lớp em?",["Cả nhóm cùng làm dự án và cùng chia sẻ kết quả","Một bạn làm, cả nhóm nhận điểm","Mỗi người tự làm riêng","Chép bài nhóm khác"]);
V("Tranh vẽ trên vách hang của người nguyên thủy cho thấy họ",["Đã có đời sống tinh thần, biết ghi lại cuộc sống","Biết dùng máy ảnh","Đã có chữ viết hoàn chỉnh","Không có tình cảm"]);
VL("s6");
V("Đồ dùng kim loại có mặt khắp nơi ngày nay bắt đầu từ phát minh nào cuối thời nguyên thủy?",["Con người biết luyện kim, chế tạo công cụ kim loại","Con người biết trồng lúa","Con người biết vẽ tranh","Con người biết làm gốm"]);
V("Hình trống đồng Đông Sơn xuất hiện trên biểu trưng, sân khấu, lễ hội ngày nay vì",["Là biểu tượng văn hóa, niềm tự hào của dân tộc Việt Nam","Là đồ chơi trẻ em","Là dụng cụ nấu ăn","Là sản phẩm nhập khẩu"]);
V("Người Việt cổ định cư ven sông Hồng, sông Mã vì",["Đất phù sa màu mỡ, có nguồn nước, thuận lợi trồng lúa","Ở đó không có ai","Để tránh xa nguồn nước","Vì đất ở đó toàn đá"]);
VL("s7");
V("Hệ đếm 60 của người Lưỡng Hà vẫn được dùng đến ngày nay khi",["Tính 1 giờ = 60 phút, 1 phút = 60 giây","Đếm tiền","Đo chiều dài","Cân khối lượng"]);
V("Lũ sông Nin vừa gây ngập vừa mang phù sa. Ở nước ta, hiện tượng tương tự là",["Mùa nước nổi ở đồng bằng sông Cửu Long","Mưa đá ở vùng núi","Bão cát ở sa mạc","Băng tan ở vùng cực"]);
V("Kim tự tháp đến nay vẫn thu hút du khách vì",["Là công trình kì vĩ, thể hiện trình độ cao của người Ai Cập cổ","Là trung tâm mua sắm","Là sân vận động","Là trường học"]);
VL("s8");
